style.css:
@-moz-document domain("chat.openai.com"), domain("chatgpt.com") {
/* ============================= */
  /*      فونت WebYekan           */
  /* ============================= */
  @font-face {
    font-family: 'WebYekan';
    src: url('https://v1.fontapi.ir/css/Yekan') format('woff2');
    font-weight: 400;
    font-style: normal;
  }

  /* ============================= */
  /*           پایه               */
  /* ============================= */
  body, .chat-root, #root, .message, .user-message, .assistant-message {
    font-family: 'WebYekan', 'IRANYekan', Tahoma, Arial, sans-serif !important;
    font-weight: 400 !important;
    background-color: #1e1e1e !important;
    color: #f5f5f5 !important;
    direction: rtl !important;
    text-align: right !important;
    line-height: 1.8 !important;
  }

  /* ============================= */
  /*          پیام‌ها              */
  /* ============================= */
  .user-message {
    background: #2e3440 !important;
    padding: 10px !important;
    border-radius: 12px !important;
    margin: 10px 0 !important;
    text-align: right !important;
    direction: rtl !important;
  }

  .assistant-message {
    background: #3b4252 !important;
    padding: 10px !important;
    border-radius: 12px !important;
    margin: 10px 0 !important;
    text-align: left !important;
    direction: rtl !important;
  }

  /* متن انگلیسی */
  p, li, span { unicode-bidi: plaintext !important; }

  /* ============================= */
  /*            تیترها              */
  /* ============================= */
  h1, h2, h3, h4, h5, h6 {
    margin-top: 1em !important;
    margin-bottom: 0.5em !important;
    font-weight: 500 !important;
  }

  h1 { color: #bf616a !important; }
  h2 { color: #a3be8c !important; }
  h3 { color: #b48ead !important; }
  h4 { color: #b48ead !important; }
  h5 { color: #8fbcbb !important; }
  h6 { color: #ebcb8b !important; }

  /* ============================= */
  /*         متن تأکیدی             */
  /* ============================= */
  strong { color: #ebcb8b !important; font-weight: 600 !important; }
  em { color: #88c0d0 !important; font-style: italic !important; }

  /* ============================= */
  /*          بلاک کدها             */
  /* ============================= */
  pre, code, pre code {
    direction: ltr !important;
    text-align: left !important;
    font-family: monospace !important;
    color: #f8f8f2 !important;
    background: #2e3440 !important;
    border-radius: 6px !important;
    padding: 6px 10px !important;
    overflow-x: auto !important;
    display: block !important;
  }

  pre code .keyword { color: #81a1c1 !important; }
  pre code .string  { color: #a3be8c !important; }
  pre code .number  { color: #b48ead !important; }
  pre code .comment { color: #616e88 !important; }

	p, li, span {
  	unicode-bidi: inherit !important;
	}

  /* ============================= */
  /*          رنگ‌ها و جزئیات       */
  /* ============================= */
  :root {
    --background-color: #2e3440;
    --strong-color: #ebcb8b;
    --em-color: #88c0d0;
    --h1-color: #bf616a;
    --h2-color: #a3be8c;
    --h3-color: #b48ead;
    --h4-color: #b48ead;
    --h5-color: #8fbcbb;
    --h6-color: #ebcb8b;
  }

  body { background-color: var(--background-color) !important; }
  strong { color: var(--strong-color) !important; }
  em { color: var(--em-color) !important; }
  h1 { color: var(--h1-color) !important; }
  h2 { color: var(--h2-color) !important; }
  h3 { color: var(--h3-color) !important; }
  h4 { color: var(--h4-color) !important; }
  h5 { color: var(--h5-color) !important; }
  h6 { color: var(--h6-color) !important; }
}
